    def execute(self, code: str, timeout: int = 60, skip_validation: bool = False, **kwargs) -> Any:
        """
        执行 Python 代码

        ⚠️ 重要：调用此方法前，确保代码块已添加 # EXEC 标记

        Args:
            code: Python 代码（必须以 # EXEC 开头）
